<?php require 'config.php';$u=require_login();page_start('Mentorship',$u);heading('YOU DO NOT HAVE TO DO IT ALONE','A little guidance. A big difference.','Connect with an experienced community mentor for your next learning step.'); ?>
<div class="grid"><?php foreach(rows("SELECT id,name,bio,interests,photo FROM users WHERE role='mentor' AND active=1 AND id<>?",[$u['id']]) as $m):?><article class="card"><span class="badge">Community mentor</span><h2><?=e($m['name'])?></h2><p><?=e($m['bio'])?></p><p class="meta">Focus: <?=e($m['interests'])?></p><form action="action.php" method="post"><?php csrf();?><input type="hidden" name="action" value="mentor_request"><input type="hidden" name="id" value="<?=$m['id']?>"><?php textarea('What would you like help with?','message');?><button class="button">Request mentorship →</button></form></article><?php endforeach;?></div>
<section class="card"><h2>Your connections</h2><?php $connections=rows('SELECT m.*,a.name member,b.name mentor FROM mentorships m JOIN users a ON a.id=m.member_id JOIN users b ON b.id=m.mentor_id WHERE member_id=? OR mentor_id=? ORDER BY id DESC',[$u['id'],$u['id']]);foreach($connections as $c):?><div class="reply"><strong><?=e($c['member'])?> → <?=e($c['mentor'])?></strong><span class="badge"><?=e(ucfirst($c['status']))?></span><p class="body-text"><?=e($c['message'])?></p><?php if($c['mentor_id']==$u['id']&&$u['role']==='mentor'&&$c['status']==='pending'):?><form method="post" action="action.php" class="inline"><?php csrf();?><input type="hidden" name="action" value="mentor_response"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button" name="status" value="accepted">Accept</button><button class="ghost" name="status" value="declined">Decline</button></form><?php endif;?></div><?php endforeach;if(!$connections)echo '<p>No requests yet. Introduce yourself to a mentor above.</p>';?></section><?php page_end(); ?>
